// LAB: Translate through a checked page map
// Translate byte addresses using 4096-byte pages and a virtual-page-to-frame map. Reject an unmapped virtual page and guard the frame multiplication.
// This starter verifies the original example. Extend it to satisfy the lab checks.
#include <cassert>
#include <iostream>

int main() {
    const unsigned page_size = 4096;
    const unsigned address = 0x1234;
    const unsigned page = address / page_size;
    const unsigned offset = address % page_size;
    const unsigned frame = 7;
    const unsigned physical = frame * page_size + offset;
    std::cout << "page=" << page << " offset=" << offset
              << " physical=" << physical << '\n';
    assert(page == 1 && offset == 564 && physical == 29236);
}

#include <cassert>
#include <cstddef>
#include <iostream>
#include <limits>
#include <map>
#include <optional>

std::optional<std::size_t> translate(std::size_t address,
    const std::map<std::size_t,std::size_t>& pages) {
    const std::size_t size = 4096;
    const auto entry = pages.find(address/size);
    if(entry == pages.end()) return std::nullopt;
    const auto offset = address%size;
    const auto maximum = std::numeric_limits<std::size_t>::max();
    if(entry->second > (maximum-offset)/size) return std::nullopt;
    return entry->second*size+offset;
}

int main() {
    std::map<std::size_t,std::size_t> pages{{1,7}};
    assert(translate(0x1234,pages) == 29236 && translate(0x1235,pages) == 29237);
    assert(!translate(0x2000,pages));
    pages[2] = std::numeric_limits<std::size_t>::max();
    assert(!translate(0x2000,pages));
    std::cout << "physical=" << *translate(0x1234,pages) << " unmapped=rejected\n";
}

